//! Authored tetrahedron fixtures generated by tests/mesh_fixture.py; no CAD originals.
use jt_core::{
    mesh::{decode_mesh_element, read_bytes, MeshOptions, ReadOptions},
    ByteOrder, ReadLimits, SourceSpan,
};
fn hex(text: &str) -> Vec<u8> {
    let text: String = text.split_whitespace().collect();
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).unwrap())
        .collect()
}
fn source(n: usize) -> SourceSpan {
    SourceSpan {
        source_id: "authored".into(),
        byte_domain: "mesh".into(),
        start_offset: 0,
        end_offset: n as u64,
    }
}
#[test]
fn pure_rust_shared_tetra_with_corner_indices_and_noncommuting_placement() {
    let input = hex(include_str!("data/tetra9-scene.hex"));
    let scene = read_bytes(
        &input,
        "authored",
        &ReadLimits::default(),
        &ReadOptions::default(),
    )
    .unwrap();
    assert!(scene.complete);
    assert_eq!(scene.meshes.len(), 1);
    assert_eq!(scene.instances.len(), 2);
    let mesh = &scene.meshes[0];
    assert_eq!(
        mesh.positions,
        [[0., 0., 0.], [1., 0., 0.], [0., 1., 0.], [0., 0., -1.]]
    );
    assert_eq!(mesh.triangles, [[0, 1, 2], [2, 1, 3], [2, 3, 0], [3, 1, 0]]);
    assert_eq!(mesh.normal_indices.as_ref().unwrap(), &mesh.triangles);
    let first = &scene.structure.model.instances[scene.instances[0].structure_instance_id as usize];
    assert_eq!(first.world_transform[0] + first.world_transform[3], 10.);
    assert_eq!(first.world_transform[4] + first.world_transform[7], 1.);
    assert_eq!(mesh.buffer_bytes(), 304);
}
#[test]
fn all_truncations_and_bounded_mutations_do_not_panic() {
    let input = hex(include_str!("data/tetra9-payload.hex"));
    let options = MeshOptions {
        max_vertices: 100,
        max_triangles: 100,
        max_mesh_bytes: 100_000,
        max_codec_values: 10_000,
        max_codec_packets: 1000,
        max_topology_edges: 1000,
        max_topology_work: 10_000,
        ..MeshOptions::default()
    };
    for end in 0..input.len() {
        assert!(
            decode_mesh_element(&input[..end], ByteOrder::Little, source(end), &options).is_err(),
            "accepted prefix {end}"
        );
    }
    for i in 0..input.len() {
        for bit in 0..8 {
            let mut changed = input.clone();
            changed[i] ^= 1 << bit;
            let _ =
                decode_mesh_element(&changed, ByteOrder::Little, source(changed.len()), &options);
        }
    }
}
